<?php require_once __DIR__.'/includes/functions.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$email=strtolower(trim($_POST['email']??''));$s=$db->prepare("SELECT id,name,is_verified FROM users WHERE email=? AND role='user'");$s->bind_param('s',$email);$s->execute();$u=$s->get_result()->fetch_assoc();if($u&&!$u['is_verified']){$token=bin2hex(random_bytes(32));$hash=hash('sha256',$token);$s=$db->prepare('INSERT INTO email_verifications(user_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 24 HOUR))');$s->bind_param('is',$u['id'],$hash);$s->execute();$sent=send_verify_email($email,$u['name'],$token);$msg=$sent?'A new verification email was sent.':'Email could not be sent. Configure the mail server.';}else $msg='If the account exists and needs verification, a new link has been sent.';}$title='Resend verification';require 'includes/header.php';?><div class="panel" style="max-width:480px"><h1>Resend verification email</h1><?php if($msg):?><div class="alert"><?=e($msg)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label>Email</label><input type="email" name="email" required><button>Resend</button></form></div><?php require 'includes/footer.php';?>
